CREATE OR REPLACE FUNCTION public.guard_return_settlement() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE original public.commerce_documents;paid numeric;returned numeric;refunds numeric;BEGIN
 IF NEW.kind IN ('sale_return','purchase_return') AND NEW.status='confirmed' THEN SELECT * INTO original FROM public.commerce_documents WHERE id=NEW.source_id;SELECT coalesce(sum(amount),0) INTO paid FROM public.commerce_payments WHERE document_id=original.id;SELECT coalesce(sum(total),0) INTO returned FROM public.commerce_documents WHERE source_id=original.id AND kind=NEW.kind AND status='confirmed';SELECT coalesce(sum(p.amount),0) INTO refunds FROM public.commerce_payments p JOIN public.commerce_documents d ON d.id=p.document_id WHERE d.source_id=original.id AND d.kind=NEW.kind;
 IF original.party_id IS NULL AND refunds<>greatest(0,paid-(original.total-returned)) THEN RAISE EXCEPTION 'Walk-in return requires full immediate refund';END IF;END IF;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public.guard_return_settlement() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.commerce_required_values() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.request IS NULL OR NEW.request->>'date' IS NULL THEN RAISE EXCEPTION 'Request date required';END IF;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public.commerce_required_values() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER commerce_required_values BEFORE INSERT ON public.commerce_documents FOR EACH ROW EXECUTE FUNCTION public.commerce_required_values();